 async function event(c:any,m:any,s:any,v:any,kind:string,before:any,after:any,sourceKey?:string){const eid=randomUUID();await c.query('insert into ab.vehicle_events(id,tenant_id,company_id,vehicle_id,request_id,actor_id,kind,payload_cipher,source_key)values($1,$2,$3,$4,$5,$6,$7,$8,$9)',[eid,s.tenant_id,v.company_id,v.vehicle?null:v.id,v.request_id||v.requestId||v.vehicle&&v.id||null,s.user_id,kind,cipher.seal({before,after}),sourceKey||null]);await audit(c,s.tenant_id,s.user_id,kind,'vehicle',v.id,Object.keys(after||{}));await notify(c,m,s,v.company_id,v.id,kind,eid);return eid;}
 async function history(c:any,v:any){return (await c.query('select * from ab.vehicle_events where '+(v.vehicle?'request_id':'vehicle_id')+'=$1 order by created_at,id',[v.id])).rows.map((r:any)=>({id:r.id,kind:r.kind,actorId:r.actor_id,createdAt:r.created_at,...cipher.open(r.payload_cipher)}));}
 async function proof(c:any,m:any,v:any,fileId:string|undefined,required=true){if(!fileId){requireOk(!required,422,'proofRequired');return null;}need(m,'documents',v.company_id);const f=(await c.query('select f.*,coalesce(r.verdict,f.scan_status) verdict from ab.vehicle_files f left join ab.vehicle_file_reviews r on r.file_id=f.id where f.id=$1',[fileId])).rows[0];requireOk(f&&f.vehicle_id===v.id,422,'invalidReference');if(required)requireOk(f.verdict==='clean',423,'fileQuarantined');return f;}
 async function customer(c:any,m:any,key:string,exception?:string){const r=(await c.query('select * from ab.customers where id=$1',[key])).rows[0];requireOk(r,404,'notFound');requireOk(customerCan(m,'view',r.company_id));if(r.status!=='Active'){requireOk(customerCan(m,'review',r.company_id));requireOk(exception?.trim(),409,'customerInactive');}return r;}
 const registration=z.object({capacityTonnes:z.string().regex(/^$|^\d{1,4}(\.\d{1,3})?$/).default(''),seats:z.string().regex(/^$|^[1-9]\d{0,2}$/).refine(v=>!v||Number(v)<=200).default(''),vehicleType:z.string().min(1).max(120),make:z.string().max(120).default(''),model:z.string().max(120).default(''),year:z.string().regex(/^$|^(19|20)\d{2}$/).default(''),color:z.string().max(80).default(''),emirate:z.string().max(80).default(''),areaId:z.string().min(1).max(100).nullish(),plate:z.string().max(80).default(''),plateCode:z.string().max(40).default(''),vin:z.string().max(40).default(''),registeredOn:optionalDay.default(''),ownershipExpiresOn:optionalDay.default(''),currency:z.string().regex(/^[A-Z]{3}$/).default('AED'),notes:text.default(''),legacyData:z.record(z.string().max(100),z.string().max(10000)).optional()}).strict();
 async function asset(c:any,s:any,d:any,prior?:any,allowedPrevious?:string){if(!d.vin)return null;const digest=cipher.digest(d.vin.replace(/[^a-z0-9]/gi,'').toUpperCase()),old=(await c.query('select * from ab.vehicle_assets where vin_digest=$1',[digest])).rows[0];if(old){const used=(await c.query("select id from ab.vehicles where asset_id=$1 and status<>'Terminated'",[old.id])).rows;requireOk(used.every((v:any)=>v.id===prior?.id||v.id===allowedPrevious),409,'duplicateVehicle');return old.id;}const key=randomUUID();await c.query('insert into ab.vehicle_assets values($1,$2,$3)',[key,s.tenant_id,digest]);return key;}
 const search=(d:any)=>[d.plate,d.plateCode,d.vin,d.make,d.model,d.emirate,d.areaId].filter(Boolean).flatMap(v=>{const n=String(v).normalize('NFKC').toLowerCase().replace(/\s+/g,'').trim();return Array.from({length:n.length},(_,i)=>cipher.digest(n.slice(0,i+1)));});
