 app.post('/api/vehicle-funds/:id/receive',route(async(c:any,m:any,s:any,req:any)=>{z.object({confirm:z.literal(true)}).strict().parse(req.body);const f=(await c.query('select * from ab.vehicle_funds where id=$1 for update',[id.parse(req.params.id)])).rows[0];requireOk(f&&f.receiver_id===s.user_id&&f.state==='AwaitingReceipt',403,'receiverOnly');need(m,'receive_funds',f.company_id);await c.query("update ab.vehicle_funds set state='Held',received_at=now()where id=$1",[f.id]);await event(c,m,s,{id:f.request_id,company_id:f.company_id,vehicle:true},'funds_received',{state:f.state},{state:'Held',fundsId:f.id});return {state:'Held'};}));
