 app.patch('/api/vehicles/:id',route(async(c:any,m:any,s:any,req:any)=>{const v=await get(c,m,req.params.id,'edit'),input=z.object({profile:registration,revision:z.number().int().positive()}).strict().parse(req.body),d=input.profile,old=vehicleData(v,cipher);requireOk(v.revision===input.revision,409,'revisionConflict');if((await c.query('select 1 from ab.vehicle_contracts where vehicle_id=$1',[v.id])).rowCount)requireOk(d.currency===old.currency&&d.registeredOn===old.registeredOn,409,'contractLocked');if(d.areaId)requireOk((await c.query('select 1 from ab.areas where id=$1 and emirate_id=$2',[d.areaId,d.emirate])).rowCount,422,'invalidSelection');if(!d.legacyData&&old.legacyData)d.legacyData=old.legacyData;const assetId=await asset(c,s,d,v);await c.query('update ab.vehicles set payload_cipher=$2,asset_id=$3,search_tokens=$4,revision=revision+1 where id=$1',[v.id,cipher.seal(d),assetId,search(d)]);await event(c,m,s,v,'updated',old,d);return {id:v.id,revision:v.revision+1};}));
